export type BundleAssembleSessionSummaryProps = {
  /**
   * Alle gepersisteerde concept‑aanvragen in dit bezoek (localStorage). Wordt samengevoegd
   * met de **live** matrix op deze pagina voor producten die nu in de bundel zitten.
   */
  drafts: readonly CertificationRequestDraft[];
};

type SessionSummaryLine = {
  productId: string;
  productLabel: string;
  categoryTrail: string;
  certKeys: readonly BundleCertKey[];
};

/**
 * Compact overzicht: elk product in de sessie met de bijbehorende gekozen certificaattypes
 * (bundle‑keys). Voor producten op de huidige bundelpagina worden de aangevinkte extra’s
 * live meegenomen, ook vóór “Bevestig selectie”.
 */
export function BundleAssembleSessionSummary({
  drafts,
}: BundleAssembleSessionSummaryProps) {
  const { products, selections } = useBundleAssemble();

  const lines = useMemo((): readonly SessionSummaryLine[] => {
    type Acc = { label: string; categoryTrail: string; certs: Set<BundleCertKey> };
    const byProduct = new Map<string, Acc>();

    for (const d of drafts) {
      const pid = d.productId?.trim();
      if (!pid) continue;
      const entry = d.entryId as string;
      if (!isBundleCertKey(entry)) continue;

      let acc = byProduct.get(pid);
      if (!acc) {
        acc = {
          label: d.productLabel ?? pid,
          categoryTrail: d.productPath ?? d.productTypeStreamLabel ?? "",
          certs: new Set(),
        };
        byProduct.set(pid, acc);
      }
      acc.certs.add(entry);
      if (d.productLabel?.trim()) acc.label = d.productLabel.trim();
      const trail = d.productPath ?? d.productTypeStreamLabel ?? "";
      if (trail.trim()) acc.categoryTrail = trail;
    }

    for (const p of products) {
      const live = new Set<BundleCertKey>();
      live.add(p.rowPrimaryCert);
      const extra = selections.get(p.id);
      if (extra) for (const c of extra) live.add(c);

      const acc =
        byProduct.get(p.id) ??
        ({
          label: p.label,
          categoryTrail: p.categoryTrail,
          certs: new Set<BundleCertKey>(),
        } satisfies Acc);

      acc.label = p.label;
      acc.categoryTrail = p.categoryTrail;
      acc.certs = live;
      byProduct.set(p.id, acc);
    }

    return Array.from(byProduct.entries())
      .map(([productId, acc]) => ({
        productId,
        productLabel: acc.label,
        categoryTrail: acc.categoryTrail,
        certKeys: BUNDLE_CERT_ORDER.filter((c) => acc.certs.has(c)),
      }))
      .sort((a, b) => a.productLabel.localeCompare(b.productLabel, "nl"));
  }, [drafts, products, selections]);

  if (lines.length === 0) return null;

  return (
    <section
      className="flex flex-col gap-component rounded-lg border border-border/70 bg-muted/25 px-component py-component"
      aria-label="Overzicht van geselecteerde producten en certificaties in dit bezoek"
    >
      <h2 className="text-base font-semibold leading-snug text-foreground">
        Uw selectie dit bezoek
      </h2>
      <p className="m-0 text-sm leading-normal text-muted-foreground">
        Alle producten met de bijbehorende certificaattypes, ook wanneer u meerdere routes
        combineert. Wijzigingen in de tabel hieronder worden meteen hier weerspiegeld.
      </p>
      <ul className="m-0 flex list-none flex-col gap-component p-0">
        {lines.map((line) => (
          <li
            key={line.productId}
            className="rounded-md border border-border/60 bg-background/80 px-component py-micro"
          >
            <div className="font-medium text-foreground">{line.productLabel}</div>
            {line.categoryTrail.trim() ? (
              <div className="mt-micro text-xs leading-normal text-muted-foreground">
                {line.categoryTrail}
              </div>
            ) : null}
            <div className="mt-component flex flex-wrap gap-micro" role="list" aria-label="Certificaattypes">
              {line.certKeys.map((k) => (
                <span
                  key={k}
                  role="listitem"
                  className="inline-flex items-center rounded-md border border-border/80 bg-muted/50 px-2 py-0.5 text-xs font-medium text-foreground"
                >
                  {BUNDLE_CERT_META[k].shortTitle}
                </span>
              ))}
            </div>
          </li>
        ))}
      </ul>
    </section>
  );
}

